import{_ as t,o as a,c as i,a4 as n}from"./chunks/framework.D-V5jUSB.js";const p=JSON.parse('{"title":"Explainable results","description":"","frontmatter":{},"headers":[],"relativePath":"en/explainable.md","filePath":"en/explainable.md"}'),o={name:"en/explainable.md"};function r(s,e,l,h,d,c){return a(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="explainable-results" tabindex="-1">Explainable results <a class="header-anchor" href="#explainable-results" aria-label="Permalink to &quot;Explainable results&quot;">​</a></h1><p>When the AI finds a film it can&#39;t just hand back a result — it has to say <strong>why this one</strong>. Every result card carries a one-line explanation, so an editor can tell at a glance whether to trust it, and can explain to a colleague why it&#39;s being recommended.</p><h2 id="the-line-on-every-result-card" tabindex="-1">The line on every result card <a class="header-anchor" href="#the-line-on-every-result-card" aria-label="Permalink to &quot;The line on every result card&quot;">​</a></h2><blockquote><p><code>matches [music][american] · semantic+guess+literal</code></p></blockquote><p>Read it in two halves:</p><p><strong>First half — which of your conditions it hit:</strong> <code>[music][american]</code> are the dimensions from your query this film matched at once (e.g. genre, region). Dimensions it didn&#39;t match aren&#39;t tacked on.</p><p><strong>Second half — how it was found:</strong> three sources, which can co-occur:</p><table tabindex="0"><thead><tr><th>Mark</th><th>Meaning</th></tr></thead><tbody><tr><td>semantic</td><td>pulled in by closeness in meaning (even if the wording differs)</td></tr><tr><td>guess</td><td>the AI imagined &quot;what the ideal film looks like,&quot; and this one matched that guess</td></tr><tr><td>literal</td><td>your query words appear directly in the title / plot</td></tr></tbody></table><h2 id="why-this-helps-editors" tabindex="-1">Why this helps editors <a class="header-anchor" href="#why-this-helps-editors" aria-label="Permalink to &quot;Why this helps editors&quot;">​</a></h2><ul><li><strong>Decide whether to trust it:</strong> &quot;only via guess, matched no conditions&quot; is a signal to stay skeptical.</li><li><strong>Explain it out loud:</strong> a concrete basis for &quot;why this film,&quot; not &quot;the system said so.&quot;</li><li><strong>Catch problems:</strong> when results look off, this line points straight at which route misfired (see <a href="/film-brain/vp-preview/en/mj-case">Debugging log</a>).</li></ul><hr><p>More: how tags are kept from being invented and how editors review them → <a href="/film-brain/vp-preview/en/auto-tag">Auto-tagging</a>; how it stays honest when nothing matches → <a href="/film-brain/vp-preview/en/honest">Honest match</a>.</p>',12)])])}const m=t(o,[["render",r]]);export{p as __pageData,m as default};
